// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;

    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(address caller, address payable recipient, uint128 deposit) public {
        vm.assume(recipient != address(0));

        uint256 amount = uint256(deposit);
        vm.deal(caller, amount);

        if (amount > 0) {
            vm.prank(caller);
            (bool sent, ) = address(c).call{value: amount}("");
            vm.assume(sent);
        }

        uint256 balanceBefore = address(c).balance;

        bool ok;
        vm.prank(caller);
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        if (caller != address(this)) {
            bool notDrained = address(c).balance == balanceBefore;
            assertTrue(!ok || notDrained);
        } else {
            assertTrue(ok || address(c).balance == balanceBefore);
        }
    }
}
